+namespace {
+struct LinkTraceTotals {
+  std::array<uint64_t, 23> Ns{};
+  std::array<uint64_t, 23> Counts{};
+  ~LinkTraceTotals() {
+    static const char *Names[] = {"frontend_codegen",
+                                  "mc_finalize",
+                                  "elf_parse",
+                                  "section_scan",
+                                  "symbol_scan",
+                                  "relocation_scan",
+                                  "allocation",
+                                  "copy",
+                                  "object_total_inclusive",
+                                  "patch",
+                                  "protect",
+                                  "context_init",
+                                  "frontend",
+                                  "lower_ra",
+                                  "mc_emit",
+                                  "function_cleanup",
+                                  "mir_verify_initial",
+                                  "mir_peephole",
+                                  "mir_dead_verify",
+                                  "x86_lower",
+                                  "phi",
+                                  "regalloc",
+                                  "post_ra"};
+    for (unsigned I = 0; I < Ns.size(); ++I)
+      if (Counts[I])
+        std::fprintf(stderr, "LINK_TRACE %s %llu %llu\n", Names[I],
+                     (unsigned long long)Counts[I], (unsigned long long)Ns[I]);
+  }
+};
+thread_local LinkTraceTotals LinkTotals;
+struct LinkTrace {
+  bool Enabled;
+  uint64_t Last;
+  static uint64_t now() {
+    return std::chrono::duration_cast<std::chrono::nanoseconds>(
+               std::chrono::steady_clock::now().time_since_epoch())
+        .count();
+  }
+  LinkTrace()
+      : Enabled(std::getenv("DTVM_LINK_TRACE")), Last(Enabled ? now() : 0) {}
+  void mark(unsigned Phase) {
+    if (!Enabled)
+      return;
+    auto Next = now();
+    LinkTotals.Ns[Phase] += Next - Last;
+    ++LinkTotals.Counts[Phase];
+    Last = Next;
+  }
+};
+} // namespace
